import express from "express";
import { fileURLToPath } from "node:url";
import {
  connectDB,
  getAllMovies,
  findMoviesByGenre,
  findMoviesFromYear,
  getTopThreeRatedMovies,
  addMovie,
} from "./database.js";

const app = express();
const PORT = 3000;

app.use(express.json());
app.use(express.static(fileURLToPath(new URL("./public", import.meta.url))));

function sendList(res, data, functionName) {
  if (!Array.isArray(data)) {
    return res.status(500).json({
      error: `${functionName}() did not return a list from the database. Complete it in database.js.`,
    });
  }
  res.json(data);
}

app.get("/api/movies", async (req, res) => {
  try {
    sendList(res, await getAllMovies(), "getAllMovies");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/movies/search", async (req, res) => {
  try {
    sendList(res, await findMoviesByGenre(req.query.genre), "findMoviesByGenre");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/movies/filter", async (req, res) => {
  const fromYear = Number(req.query.fromYear);
  if (Number.isNaN(fromYear)) {
    return res.status(400).json({ error: "Please enter a number." });
  }
  try {
    sendList(res, await findMoviesFromYear(fromYear), "findMoviesFromYear");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/movies/top", async (req, res) => {
  try {
    sendList(res, await getTopThreeRatedMovies(), "getTopThreeRatedMovies");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post("/api/movies", async (req, res) => {
  try {
    const saved = await addMovie(req.body);
    if (!saved) {
      return res.status(500).json({
        error: "addMovie() did not return the saved movie. Complete it in database.js.",
      });
    }
    res.status(201).json(saved);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

try {
  await connectDB();
} catch (err) {
  console.log("Could not connect to MongoDB:", err.message);
}

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
